            const targetFrequencyLpmm = targetFreqEl ? Number(targetFreqEl.value) : 30;
            const defocusMinMm = minDefocusEl ? Number(minDefocusEl.value) : -0.1;
            const defocusMaxMm = maxDefocusEl ? Number(maxDefocusEl.value) : 0.1;
